contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address adr, bytes memory data, uint value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (value)); require(value <= 1000000000000000000000000000000);
        require(address(this).balance >= value);
        require(msg.sender != address(this));
        bool ownerReverted;
        bool nonOwnerReverted;

        c.Command{value: value}(adr, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            ownerReverted = true;
        } else {
            ownerReverted = false;
        }

        address savedOwner = c.Owner(); if (__ESBMC_reverted()) return;
        require(savedOwner == address(this));

        nonOwnerReverted = true;

        assert(nonOwnerReverted && (ownerReverted == false || ownerReverted == true));
    }

    receive() external payable {}
}

