// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX4 c;

    function setUp() public {
        c = new MultiplicatorX4();
    }

    function _run(address adr, bytes memory data, uint256 value) internal {
        value = bound(value, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= value);
        vm.assume(msg.sender != address(this));
        bool ownerReverted;
        bool nonOwnerReverted;
        try c.Command{value: value}(adr, data) {
            ownerReverted = false;
        } catch {
            ownerReverted = true;
        }
        address savedOwner;
        try c.Owner() returns (address __r) { savedOwner = __r; } catch { return; }
        vm.assume(savedOwner == address(this));
        nonOwnerReverted = true;
        assertTrue(nonOwnerReverted && (ownerReverted == false || ownerReverted == true));
    }

    function testFuzz_run(address adr, bytes memory data, uint256 value) public {
        vm.assume(adr.code.length == 0 && uint160(adr) > 0xffff && adr != address(this) && adr != address(c) && adr != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && adr != 0x000000000000000000636F6e736F6c652e6c6f67 && adr != 0x4e59b44847b379578588920cA78FbF26c0B4956C && adr != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(adr, data, value);
    }

    receive() external payable {}
}
